def solve_n(n):
    found_solutions = []
    MAX_X = 10  # Searching small values

    if n < 3:
        return []

    # Iterate over possible starting values x1 and x2
    for x1 in range(1, MAX_X + 1):
        for x2 in range(1, MAX_X + 1):

            # --- Calculate x3 (Condition for i=2) ---
            numerator_3 = x2**2 + 1
            denominator_3 = x1 + 1

            if numerator_3 % denominator_3 != 0:
                continue

            x3 = (numerator_3 // denominator_3) - 1
            if x3 < 1:
                continue

            # Check if n=3 solution exists
            if n == 3:
                found_solutions.append((x1, x2, x3))
                continue

            # --- Calculate x4 (Condition for i=3) ---
            if n >= 4:
                numerator_4 = x3**2 + 1
                denominator_4 = x2 + 1

                if numerator_4 % denominator_4 != 0:
                    continue

                x4 = (numerator_4 // denominator_4) - 1
                if x4 < 1:
                    continue

                # Check if n=4 solution exists
                if n == 4:
                    found_solutions.append((x1, x2, x3, x4))
                    continue

                # --- Calculate x5 (Condition for i=4) ---
                if n >= 5:
                    numerator_5 = x4**2 + 1
                    denominator_5 = x3 + 1

                    if numerator_5 % denominator_5 != 0:
                        continue

                    x5 = (numerator_5 // denominator_5) - 1
                    if x5 < 1:
                        continue

                    # Check if n=5 solution exists
                    if n == 5:
                        found_solutions.append((x1, x2, x3, x4, x5))
                        continue

    return found_solutions

