def solve_n4():
    solutions = []
    limit = 50

    for x1 in range(1, limit + 1):
        for x2 in range(1, limit + 1):
            # Step 1: Calculate x3
            numerator_x3 = x2*x2 + 1
            denominator_x3 = x1 + 1

            if numerator_x3 % denominator_x3 == 0:
                x3_plus_1 = numerator_x3 // denominator_x3
                x3 = x3_plus_1 - 1

                # x3 must be a positive integer (since x1, x2 >= 1, x3+1 >= 1/2, x3 >= 0. We need x3 >= 1)
                # Since x2 >= 1, x2^2+1 >= 2. Since x1 <= 50, x1+1 <= 51. x3+1 >= 2/51 > 0.
                # If x3+1 = 1, x3=0, which is not positive. x3+1=1 implies x2^2+1 = x1+1.
                if x3 < 1:
                    continue

                # Step 2: Calculate x4
                numerator_x4 = x3*x3 + 1
                denominator_x4 = x2 + 1

                if numerator_x4 % denominator_x4 == 0:
                    x4_plus_1 = numerator_x4 // denominator_x4
                    x4 = x4_plus_1 - 1

                    # x4 must be a positive integer
                    if x4 >= 1:
                        solutions.append((x1, x2, x3, x4))

    return solutions

